import sys

def main():
    s = sys.stdin.readline().strip()

    vowels_count = 0
    consonants_count = 0

    vowel_set = set('aeiouAEIOU')

    for char in s:
        if char.isalpha():
            if char in vowel_set:
                vowels_count += 1
            else:
                consonants_count += 1

    print(f"Vowels: {vowels_count}, Consonants: {consonants_count}")

if __name__ == "__main__":
    main()
